#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll INF=4e18;struct E{int u,v,w;};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;while(cin>>n>>m&&n){int s,d;cin>>s>>d;vector<E>e(m);vector<vector<pair<int,int>>>g(n),rg(n);for(int i=0;i<m;++i){cin>>e[i].u>>e[i].v>>e[i].w;g[e[i].u].push_back({e[i].v,i});rg[e[i].v].push_back({e[i].u,i});}auto dij=[&](int src,const vector<vector<pair<int,int>>>&a,const vector<char>&ban){vector<ll>ds(n,INF);priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>q;ds[src]=0;q.push({0,src});while(!q.empty()){auto [du,u]=q.top();q.pop();if(du!=ds[u])continue;for(auto [v,id]:a[u])if(!ban[id]&&ds[v]>du+e[id].w)ds[v]=du+e[id].w,q.push({ds[v],v});}return ds;};vector<char>none(m),ban(m);auto a=dij(s,g,none),b=dij(d,rg,none);if(a[d]!=INF)for(int i=0;i<m;++i)if(a[e[i].u]!=INF&&b[e[i].v]!=INF&&a[e[i].u]+e[i].w+b[e[i].v]==a[d])ban[i]=1;auto ans=dij(s,g,ban);cout<<(ans[d]==INF?-1:ans[d])<<'\n';}}
